python3 - <<'PY'
import csv
from datetime import date
AUDIT = date(2026,3,31)
def pd(s):
    if not s or s=="none": return None
    y,m,d=s.split("-"); return date(int(y),int(m),int(d))
reg={}
for r in csv.DictReader(open("/app/input/licensed_property_register.csv")): reg[r["license_id"]]=r
eff={lid:dict(x) for lid,x in reg.items()}
for lid,x in reg.items():
    s=x["supersedes"]
    if s and s!="none":
        eff[s]=dict(x); eff[lid]=dict(x)
def cov(lid,lt,d):
    if not lid or lid=="none": return None
    row=eff.get(lid)
    if not row or row["license_type"]!=lt: return None
    c=row["covers_distribution"]
    if c!="all" and d not in c.split(";"): return None
    v=pd(row["valid_until"])
    if not v or v<AUDIT: return None
    return (lid,row["covers_distribution"],row["valid_until"],row["supersedes"])

rows=[r for r in csv.DictReader(open("/app/input/composite_request_log.csv")) if r["intake_status"]!="withdrawn"]

print("== character requests: how cleared ==")
for r in rows:
    if r["character_property"]=="none": continue
    d=r["intended_distribution"]; lid=r["character_license_id"]
    c=cov(lid,"character",d)
    if c:
        print(r["request_id"],r["character_property"],"LIC",lid,"-> covered by",c[0],"(cov",c[1],"vu",c[2],"supersedes",c[3],")")
    elif d=="personal_only":
        print(r["request_id"],r["character_property"],"LIC",lid,"-> NOT covered by licence; CLEARED by personal-use allowance (personal_only)")
    else:
        print(r["request_id"],r["character_property"],"LIC",lid,"-> NOT covered; finding UNLICENSED_CHARACTER_USE (dist",d,")")

print("\n== third_party_licensed backgrounds ==")
for r in rows:
    if r["background_source"]!="third_party_licensed": continue
    d=r["intended_distribution"]; lid=r["background_license_id"]
    c=cov(lid,"background",d)
    if c:
        print(r["request_id"],"bg LIC",lid,"-> covered by",c[0],"(cov",c[1],"vu",c[2],"supersedes",c[3],")")
    else:
        print(r["request_id"],"bg LIC",lid,"-> NOT covered (dist",d,") -> finding")

print("\n== personal-use allowance clears (character, personal_only) ==")
for r in rows:
    if r["character_property"]!="none" and r["intended_distribution"]=="personal_only":
        print(r["request_id"])
PY
